/**
 * Atmos — WMO Weather Code Interpreter & Uploaded Climate Image Icon Renderer (forecast.js)
 * Uses icons extracted directly from the user-provided Climate & Weather Icons image.
 */
const AtmosForecast = (() => {
  const CLIMATE_ICON_PATHS = {
    'sun': 'data:image/png;base64,',
    'moon': 'data:image/png;base64,',
    'cloud-rain': 'data:image/png;base64,',
    'rain': 'data:image/png;base64,',
    'cloud-wind': 'data:image/png;base64,',
    'storm': 'data:image/png;base64,',
    'snow': 'data:image/png;base64,',
    'climate': 'data:image/png;base64,'
  };

  /**
   * Maps WMO Weather interpretation codes (WW) to condition label and icon key
   */
  function getWeatherInfo(code, isDay = 1) {
    const c = Number(code);
    if (c === 0) return { label: isDay ? 'Sunny' : 'Clear Night', art: isDay ? 'sun' : 'moon' };
    if (c === 1) return { label: isDay ? 'Mostly Sunny' : 'Mostly Clear', art: isDay ? 'sun' : 'moon' };
    if (c === 2) return { label: 'Partly Cloudy', art: 'cloud-rain' };
    if (c === 3) return { label: 'Overcast', art: 'cloud-wind' };
    if (c === 45 || c === 48) return { label: 'Foggy Mist', art: 'cloud-wind' };
    if ([51, 53, 55, 56, 57].includes(c)) return { label: 'Light Drizzle', art: 'rain' };
    if ([61, 63, 65, 66, 67, 80, 81, 82].includes(c)) return { label: 'Rain Showers', art: 'rain' };
    if ([71, 73, 75, 77, 85, 86].includes(c)) return { label: 'Snowfall', art: 'snow' };
    if ([95, 96, 99].includes(c)) return { label: 'Thunderstorm', art: 'storm' };
    return { label: 'Cloudy', art: 'cloud-wind' };
  }

  /**
   * Renders the weather icon extracted from the uploaded Climate Image
   */
  function getWeatherSvg(artType, size = 56) {
    const src = CLIMATE_ICON_PATHS[artType] || CLIMATE_ICON_PATHS['cloud-rain'];
    return `<img class="weather-svg-anim" src="${src}" alt="${artType}" style="width:${size}px;height:${size}px;object-fit:contain;display:block;filter:drop-shadow(0 4px 10px rgba(0,163,224,0.22));" />`;
  }

  function windDegToCompass(deg) {
    const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
    const ix = Math.round(((Number(deg) || 0) % 360) / 45) % 8;
    return dirs[ix];
  }

  function formatTime(isoString, format = '12h') {
    if (!isoString) return '--:--';
    const d = new Date(isoString);
    if (isNaN(d.getTime())) {
      const parts = String(isoString).split('T');
      return parts[1] ? parts[1].slice(0, 5) : isoString;
    }
    return d.toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit',
      hour12: format !== '24h'
    });
  }

  return {
    getWeatherInfo,
    getWeatherSvg,
    windDegToCompass,
    formatTime
  };
})();
